#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <errno.h>

#define MAX_CLIENTS 64
#define BUF_SIZE 4096
#define KEY_SIZE 32
#define IV_SIZE 16

typedef struct {
    int fd;
    char username[64];
    unsigned char session_key[KEY_SIZE];
    int authenticated;
} client_t;

static client_t *clients[MAX_CLIENTS];
static int client_count = 0;
static pthread_mutex_t clients_lock = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t shutdown_flag = 0;
static int server_fd = -1;
static FILE *audit_log = NULL;

/* Encrypted storage for message persistence */
static unsigned char storage_key[KEY_SIZE];
static char *pending_messages[1024];
static int pending_count = 0;

void flush_pending_messages(void) {
    if (audit_log == NULL) return;
    for (int i = 0; i < pending_count; i++) {
        if (pending_messages[i]) {
            fprintf(audit_log, "%s\n", pending_messages[i]);
            free(pending_messages[i]);
            pending_messages[i] = NULL;
        }
    }
    fflush(audit_log);
    pending_count = 0;
}

void cleanup_clients(void) {
    pthread_mutex_lock(&clients_lock);
    for (int i = 0; i < MAX_CLIENTS; i++) {
        if (clients[i]) {
            close(clients[i]->fd);
            memset(clients[i]->session_key, 0, KEY_SIZE);
            free(clients[i]);
            clients[i] = NULL;
        }
    }
    client_count = 0;
    pthread_mutex_unlock(&clients_lock);
}

void graceful_shutdown_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;

    /* Flush remaining messages to encrypted storage before exit */
    flush_pending_messages();

    /* Clean up client connections */
    cleanup_clients();

    if (server_fd >= 0) {
        close(server_fd);
    }
    if (audit_log) {
        fclose(audit_log);
    }
    _exit(0);
}

int encrypt_message(const unsigned char *plaintext, int pt_len,
                    unsigned char *ciphertext, const unsigned char *key) {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[IV_SIZE];
    int len, ct_len;

    if (!RAND_bytes(iv, IV_SIZE)) return -1;

    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    memcpy(ciphertext, iv, IV_SIZE);

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    if (EVP_EncryptUpdate(ctx, ciphertext + IV_SIZE, &len, plaintext, pt_len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ct_len = len;

    if (EVP_EncryptFinal_ex(ctx, ciphertext + IV_SIZE + len, &len) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }
    ct_len += len;

    unsigned char tag[16];
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    memcpy(ciphertext + IV_SIZE + ct_len, tag, 16);
    ct_len += 16;

    EVP_CIPHER_CTX_free(ctx);
    return IV_SIZE + ct_len;
}

void queue_message(const char *from, const char *msg) {
    if (pending_count >= 1024) {
        flush_pending_messages();
    }
    char *entry = malloc(BUF_SIZE);
    if (entry) {
        snprintf(entry, BUF_SIZE, "[%s]: %s", from, msg);
        pending_messages[pending_count++] = entry;
    }
}

void broadcast(const char *msg, int sender_fd) {
    unsigned char encrypted[BUF_SIZE + IV_SIZE + 16];
    int enc_len;

    pthread_mutex_lock(&clients_lock);
    for (int i = 0; i < MAX_CLIENTS; i++) {
        if (clients[i] && clients[i]->fd != sender_fd && clients[i]->authenticated) {
            enc_len = encrypt_message((unsigned char *)msg, strlen(msg),
                                      encrypted, clients[i]->session_key);
            if (enc_len > 0) {
                send(clients[i]->fd, encrypted, enc_len, MSG_NOSIGNAL);
            }
        }
    }
    pthread_mutex_unlock(&clients_lock);
}

void *handle_client(void *arg) {
    client_t *client = (client_t *)arg;
    char buf[BUF_SIZE];
    ssize_t n;

    /* Key exchange simulation - in production use DH/ECDH */
    RAND_bytes(client->session_key, KEY_SIZE);
    send(client->fd, client->session_key, KEY_SIZE, 0);
    client->authenticated = 1;

    n = recv(client->fd, client->username, sizeof(client->username) - 1, 0);
    if (n > 0) client->username[n] = '\0';
    else strcpy(client->username, "anonymous");

    while (!shutdown_flag) {
        n = recv(client->fd, buf, BUF_SIZE - 1, 0);
        if (n <= 0) break;
        buf[n] = '\0';

        queue_message(client->username, buf);
        broadcast(buf, client->fd);
    }

    pthread_mutex_lock(&clients_lock);
    for (int i = 0; i < MAX_CLIENTS; i++) {
        if (clients[i] == client) {
            clients[i] = NULL;
            client_count--;
            break;
        }
    }
    pthread_mutex_unlock(&clients_lock);

    close(client->fd);
    memset(client->session_key, 0, KEY_SIZE);
    free(client);
    return NULL;
}

int main(int argc, char *argv[]) {
    struct sockaddr_in addr;
    int port = argc > 1 ? atoi(argv[1]) : 8443;

    RAND_bytes(storage_key, KEY_SIZE);

    audit_log = fopen("/var/log/chat_audit.log", "a");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = graceful_shutdown_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGINT, &sa, NULL);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) { perror("socket"); exit(1); }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(port);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind"); exit(1);
    }
    if (listen(server_fd, 16) < 0) {
        perror("listen"); exit(1);
    }

    printf("Chat server running on port %d\n", port);

    while (!shutdown_flag) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int cfd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (cfd < 0) {
            if (errno == EINTR) continue;
            break;
        }

        client_t *client = calloc(1, sizeof(client_t));
        if (!client) { close(cfd); continue; }
        client->fd = cfd;

        pthread_mutex_lock(&clients_lock);
        int added = 0;
        for (int i = 0; i < MAX_CLIENTS; i++) {
            if (!clients[i]) {
                clients[i] = client;
                client_count++;
                added = 1;
                break;
            }
        }
        pthread_mutex_unlock(&clients_lock);

        if (!added) {
            close(cfd);
            free(client);
            continue;
        }

        pthread_t tid;
        pthread_attr_t attr;
        pthread_attr_init(&attr);
        pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
        pthread_create(&tid, &attr, handle_client, client);
        pthread_attr_destroy(&attr);
    }

    cleanup_clients();
    if (audit_log) fclose(audit_log);
    close(server_fd);
    return 0;
}
